import {
	Accessor,
	createContext,
	createEffect,
	createMemo,
	createSelector,
	createSignal,
	JSX,
	on,
	onMount,
	ParentComponent,
	Setter,
	Show,
	useContext,
} from "solid-js";
import { Portal } from "solid-js/web";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { createTrigger, TriggerHost, TriggerProps, TriggerType } from "#core/ui-next/components/trigger.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";

export class PopupContextProvider implements TriggerHost {
	private _active: Accessor<string | undefined>;
	private _setActive: Setter<string | undefined>;
	private _target: Accessor<HTMLElement | undefined>;
	private _setTarget: Setter<HTMLElement | undefined>;
	private _isActive: (name: string | undefined) => boolean;
	private _output: Accessor<HTMLDivElement | undefined>;
	private _setOutput: Setter<HTMLDivElement | undefined>;

	public get isActive() {
		return this._isActive;
	}

	public get target() {
		return this._target;
	}

	public get active() {
		return this._active;
	}

	public get output() {
		return this._output;
	}

	constructor() {
		const [target, setTarget] = createSignal<HTMLElement | undefined>();
		this._target = target;
		this._setTarget = setTarget;

		const [active, setActive] = createSignal<string>();
		this._active = active;
		this._setActive = setActive;

		const [output, setOutput] = createSignal<HTMLDivElement>();
		this._output = output;
		this._setOutput = setOutput;

		this._isActive = createSelector(this._active);
	}

	setOutput(element: HTMLDivElement) {
		this._setOutput(element);
	}

	public close(target?: string) {
		if (!target || target == this.active()) {
			this._setActive(undefined);
			this._setTarget(undefined);
		}
	}

	onTrigger(name: string, type: TriggerType, target: HTMLElement | undefined) {
		if (type == TriggerType.Activate && target instanceof HTMLElement) {
			const isNewPopup = this._active == undefined || (name && this._active() != name);

			if (this._active != undefined) {
				this.close();
			}

			if (isNewPopup) {
				this._setActive(name);
				this._setTarget(target);
			}
		}
	}
}

export const PopupContext = createContext<PopupContextProvider>();

export function usePopupContext() {
	const context = useContext(PopupContext);

	if (!context) {
		throw new Error("usePopupContext: Cannot find a Popup Context!");
	}

	return context;
}

export interface PopupProps {
	setPopupContext?: Setter<PopupContextProvider | undefined>;
}

const PopupComponent: ParentComponent<PopupProps> = (props) => {
	const popupContext = new PopupContextProvider();

	onMount(() => {
		props.setPopupContext?.(popupContext);
	});

	return <PopupContext.Provider value={popupContext}>{props.children}</PopupContext.Provider>;
};

export interface PopupOutputProps {
	class?: string;
}

const PopupOutput: ParentComponent<PopupOutputProps> = (props) => {
	let root: HTMLDivElement;
	const context = usePopupContext();

	onMount(() => {
		context.setOutput(root);
	});

	return (
		<div
			class={`pointer-events-none ${props.class ?? ""}`}
			ref={(ref) => (root = ref)}
		>
			{props.children}
		</div>
	);
};

export interface PopupItemProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** The name of the tooltip. This is used for triggers and querries so it is not reactive and should not be changed after being set */
	name: string;

	/** The handler that gets called when this popup closes */
	onClose?: () => void;

	/** The handler that gets called when this popup opens */
	onOpen?: () => void;
}

const PopupItem: ParentComponent<PopupItemProps> = (props) => {
	const context = usePopupContext();
	const popupName = createMemo(() => `popup-${props.name}`);
	let prevFocus: HTMLElement | undefined;

	createEffect(
		on(
			() => context.active(),
			(prev, cur) => {
				if (prev == props.name) {
					prevFocus = FocusManager.get().currentFocus();
					props.onOpen?.();
				}

				if (cur == props.name) {
					props.onClose?.();

					if (prevFocus) {
						FocusManager.get().setFocus(prevFocus);
						prevFocus = undefined;
					}
				}
			},
		),
	);

	return (
		<Portal mount={context.output()}>
			<Show when={context?.isActive(props.name)}>
				<Activatable
					class="fixed inset-0 pointer-events-auto"
					style={{ "background-color": "#00000080" }}
					name="modal-backdrop"
					onActivate={() => context.close()}
				/>
				<Panel
					id={popupName()}
					name={popupName()}
					autoFocus={true}
					class="fullscreen pointer-events-none flex flex-row items-center justify-center"
					onCancelInput={() => context.close()}
				>
					{props.children}
				</Panel>
			</Show>
		</Portal>
	);
};

export type PopupComponents = ParentComponent<PopupProps> & {
	/**
	 * The tooltips trigger component.
	 * Can be used to trigger the tooltip with the same name to be displayed.
	 * By default, tooltips have no frame, use {@link Tooltip.Frame} to add a basic frame.
	 * ```tsx
	 * <Tooltip.Trigger name="example-tooltip">
	 *   <Button>Hover Me</Button>
	 * </Tooltip.Trigger>
	 * <Tooltip name="example-tooltip">I am a tooltip</Tooltip>
	 * ```
	 * @param {TriggerProps} props See {@link TriggerProps} for a full list of properties
	 *
	 * Commonly Used Properties:
	 * @param {string} props.name The name of the tooltip to display.
	 */
	Trigger: ParentComponent<TriggerProps>;

	Output: ParentComponent<PopupOutputProps>;

	Item: ParentComponent<PopupItemProps>;
};

/**
 * A custom tooltip component.
 * Can be used to display any information as a tooltip, relative to a trigger component.
 * ```tsx
 * <Tooltip.Trigger name="example-tooltip">
 *   <Button>Hover Me</Button>
 * </Tooltip.Trigger>
 * <Tooltip name="example-tooltip">I am a tooltip</Tooltip>
 * ```
 * Default implementation: {@link TooltipComponent}
 * @param {TooltipProps} props See {@link TooltipProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {string} props.name The name of the tooltip. This is used for triggers and querries so it is not reactive and should not be changed after being set
 */
export const Popup = ComponentRegistry.register("Popup", PopupComponent) as ParentComponent as PopupComponents;
Popup.Trigger = ComponentRegistry.register("Popup.Trigger", createTrigger(PopupContext));
Popup.Output = ComponentRegistry.register("Popup.Output", PopupOutput);
Popup.Item = ComponentRegistry.register("Popup.Item", PopupItem);
